package pe.fiberlux.nexus.util;
import java.nio.charset.StandardCharsets;
import java.io.*;
import java.lang.reflect.*;
import java.text.Normalizer;
import java.util.*;
import java.util.zip.*;

/** PDF y XLSX válidos; Apache POI se usa automáticamente si está disponible en Maven. */
public final class Exports {
 public static byte[] csv(List<List<String>> rows){StringBuilder s=new StringBuilder("\ufeff");for(List<String> r:rows){for(int i=0;i<r.size();i++){if(i>0)s.append(',');s.append('"').append(r.get(i).replace("\"","\"\"")).append('"');}s.append("\r\n");}return s.toString().getBytes(StandardCharsets.UTF_8);}
 public static byte[] xlsx(List<List<String>> rows){try{Class<?> book=Class.forName("org.apache.poi.xssf.usermodel.XSSFWorkbook");Object wb=book.getConstructor().newInstance();Object sheet=book.getMethod("createSheet",String.class).invoke(wb,"Reporte SLA");Class<?> sheetType=Class.forName("org.apache.poi.ss.usermodel.Sheet"),rowType=Class.forName("org.apache.poi.ss.usermodel.Row"),cellType=Class.forName("org.apache.poi.ss.usermodel.Cell");Method cr=sheetType.getMethod("createRow",int.class),cc=rowType.getMethod("createCell",int.class),set=cellType.getMethod("setCellValue",String.class);for(int i=0;i<rows.size();i++){Object r=cr.invoke(sheet,i);for(int j=0;j<rows.get(i).size();j++)set.invoke(cc.invoke(r,j),rows.get(i).get(j));}ByteArrayOutputStream b=new ByteArrayOutputStream();book.getMethod("write",OutputStream.class).invoke(wb,b);book.getMethod("close").invoke(wb);Integrations.log("Reporte XLSX creado con Apache POI");return b.toByteArray();}catch(ClassNotFoundException absent){return nativeXlsx(rows);}catch(Exception ex){throw new IllegalStateException("Error al generar Excel con Apache POI",ex);}}
 private static byte[] nativeXlsx(List<List<String>> rows){try{ByteArrayOutputStream bytes=new ByteArrayOutputStream();try(ZipOutputStream zip=new ZipOutputStream(bytes,StandardCharsets.UTF_8)){
  entry(zip,"[Content_Types].xml","<?xml version=\"1.0\"?><Types xmlns=\"http://schemas.openxmlformats.org/package/2006/content-types\"><Default Extension=\"rels\" ContentType=\"application/vnd.openxmlformats-package.relationships+xml\"/><Default Extension=\"xml\" ContentType=\"application/xml\"/><Override PartName=\"/xl/workbook.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml\"/><Override PartName=\"/xl/worksheets/sheet1.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml\"/></Types>");
  entry(zip,"_rels/.rels","<?xml version=\"1.0\"?><Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\"><Relationship Id=\"rId1\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument\" Target=\"xl/workbook.xml\"/></Relationships>");
  entry(zip,"xl/workbook.xml","<?xml version=\"1.0\"?><workbook xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\" xmlns:r=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships\"><sheets><sheet name=\"Reporte SLA\" sheetId=\"1\" r:id=\"rId1\"/></sheets></workbook>");
  entry(zip,"xl/_rels/workbook.xml.rels","<?xml version=\"1.0\"?><Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\"><Relationship Id=\"rId1\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet\" Target=\"worksheets/sheet1.xml\"/></Relationships>");
  StringBuilder xml=new StringBuilder("<?xml version=\"1.0\" encoding=\"UTF-8\"?><worksheet xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\"><sheetData>");for(int i=0;i<rows.size();i++){xml.append("<row r=\"").append(i+1).append("\">");List<String> row=rows.get(i);for(int j=0;j<row.size();j++){int col=j;StringBuilder c=new StringBuilder();do{c.insert(0,(char)('A'+col%26));col=col/26-1;}while(col>=0);xml.append("<c r=\"").append(c).append(i+1).append("\" t=\"inlineStr\"><is><t>").append(escape(row.get(j))).append("</t></is></c>");}xml.append("</row>");}xml.append("</sheetData></worksheet>");entry(zip,"xl/worksheets/sheet1.xml",xml.toString());}return bytes.toByteArray();}catch(Exception e){throw new IllegalStateException(e);}}
 private static String escape(String s){return s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;");}
 private static void entry(ZipOutputStream z,String p,String s)throws IOException{z.putNextEntry(new ZipEntry(p));z.write(s.getBytes(StandardCharsets.UTF_8));z.closeEntry();}
 public static byte[] pdf(String title,List<String> lines){try{
  List<String> text=new ArrayList<>();text.add(title);text.add("Fiberlux SAC - NexusDesk NOC");text.addAll(lines);
  StringBuilder stream=new StringBuilder("BT /F1 18 Tf 48 794 Td ");for(int i=0;i<text.size()&&i<35;i++){if(i==2)stream.append("/F1 11 Tf ");if(i!=0)stream.append("0 -22 Td ");String ascii=Normalizer.normalize(text.get(i),Normalizer.Form.NFD).replaceAll("\\p{M}","").replaceAll("[^\\x20-\\x7E]"," ").replace("\\","\\\\").replace("(","\\(").replace(")","\\)");stream.append("(").append(ascii).append(") Tj ");}stream.append("ET");
  String[] objects={"<< /Type /Catalog /Pages 2 0 R >>","<< /Type /Pages /Kids [3 0 R] /Count 1 >>","<< /Type /Page /Parent 2 0 R /MediaBox [0 0 595 842] /Resources << /Font << /F1 4 0 R >> >> /Contents 5 0 R >>","<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica >>","<< /Length "+stream.toString().getBytes(StandardCharsets.US_ASCII).length+" >>\nstream\n"+stream+"\nendstream"};
  ByteArrayOutputStream b=new ByteArrayOutputStream();b.write("%PDF-1.4\n".getBytes(StandardCharsets.US_ASCII));List<Integer> offsets=new ArrayList<>();offsets.add(0);for(int i=0;i<objects.length;i++){offsets.add(b.size());b.write((i+1+" 0 obj\n"+objects[i]+"\nendobj\n").getBytes(StandardCharsets.US_ASCII));}int xref=b.size();b.write(("xref\n0 "+(objects.length+1)+"\n0000000000 65535 f \n").getBytes(StandardCharsets.US_ASCII));for(int i=1;i<offsets.size();i++)b.write(String.format("%010d 00000 n \n",offsets.get(i)).getBytes(StandardCharsets.US_ASCII));b.write(("trailer\n<< /Size "+(objects.length+1)+" /Root 1 0 R >>\nstartxref\n"+xref+"\n%%EOF").getBytes(StandardCharsets.US_ASCII));return b.toByteArray();
 }catch(IOException e){throw new IllegalStateException(e);}}
}
